const $=s=>document.querySelector(s)
const panel=document.createElement('div');panel.id='dice-management';panel.className='grid'
panel.innerHTML=`<section><h2>本群KP</h2><p class="note">每个群分别记录KP。在群内也可使用.kp @某人、.kp 我、.kp 查看、.kp 清除；修改指令仅机器人管理员或本群管理可用。</p><label for="kp-group">选择群</label><select id="kp-group"></select><p id="kp-current" role="status"></p><label for="kp-uid">KP的QQ号</label><input id="kp-uid" inputmode="numeric" placeholder="输入KP的QQ号" maxlength="20"><label for="kp-name">KP称呼（可选）</label><input id="kp-name" placeholder="留空显示QQ号" maxlength="40"><button id="kp-save">保存本群KP</button> <button id="kp-remove">清除本群KP</button><p class="note">KP记录用于确认主持人身份，不赋予QQ管理权限；暗骰仍只发给掷骰者。</p><details><summary>已记录的KP</summary><pre id="keeper-list">读取中…</pre></details></section><section><h2>清空所有玩家记录</h2><p>一次清理全部群聊及私聊中的骰子玩家角色卡、SAN、个人默认骰面与累计骰点计数。</p><p class="note">保留KP、群骰子开关及防重复投递记录；不清除QQ群聊天记录、AI记忆或书库。</p><p class="note">清理前自动备份骰子数据，最近5份保存在airunning/.data/dice-backups。</p><button id="dice-clear-players" class="dice-danger">一键清空所有玩家记录</button><p><button id="dice-manage-refresh">刷新KP与记录状态</button></p><p id="dice-player-count" class="note"></p><p id="dice-management-result" role="status" style="overflow-wrap:anywhere"></p></section>`
$('main').insertBefore(panel,$('main').lastElementChild)
const stage=document.createElement('section');stage.id='dice-theatre';stage.style.gridColumn='1 / -1';stage.innerHTML=`<h2>NPC背景与人格模拟</h2><p class="note">以下设置属于上方选择的群。KP私聊：.npc 群号 NPC名 背景；.npc use 群号 NPC名。群内发送 人格模拟：【PL具体做了什么行动】，使用当前NPC；KP也可以私聊模拟。背景仅用于模型扮演，不会直接发送到群里。</p><label><input id="theatre-enabled" type="checkbox">启用本群人格模拟</label><label><input id="theatre-commentary" type="checkbox">掷骰后附加一两句AI点评（暗骰点评仅私聊）</label><label for="theatre-max">模拟正文最多字数（80–2000）</label><input id="theatre-max" type="number" min="80" max="2000" step="1"><label for="theatre-prompt">NPC模拟引导</label><textarea id="theatre-prompt" rows="4" maxlength="4000"></textarea><label for="theatre-comment-prompt">骰点点评引导</label><textarea id="theatre-comment-prompt" rows="3" maxlength="4000"></textarea><button id="theatre-save">保存本群模拟与点评设置</button><hr><label for="npc-list">选择要编辑的NPC（不影响其他NPC启用）</label><select id="npc-list"></select><label for="npc-name">NPC名称</label><input id="npc-name" maxlength="40" placeholder="新增时输入新名称"><label for="npc-background">NPC背景、性格、说话习惯与秘密（修改后所有群共用）</label><textarea id="npc-background" rows="8" maxlength="20000" placeholder="由KP编写的背景故事，最多20000字"></textarea><div class="presets"><button id="npc-save">保存NPC背景</button><button id="npc-select">启用并设为默认NPC</button><button id="npc-new">填写新NPC</button><button id="npc-delete">删除此NPC</button><button id="npc-history-clear">清除本群模拟上下文</button></div><p id="npc-active" role="status"></p><p class="note">模拟只发一条纯文本：青娥模拟：【NPC动作或对白】。每个会话仅保留最近6轮模拟，群聊与KP私聊互相隔离；修改背景会重置模拟上下文。清空玩家角色卡不会删除NPC背景。普通掷骰没有判定阈值时，点评不擅自裁定成功或失败。</p>`;panel.insertBefore(stage,panel.lastElementChild)
panel.append(stage);const feedback=document.createElement('p');feedback.id='theatre-result';feedback.setAttribute('role','status');stage.append(feedback)
const aliasLabel=document.createElement('label');aliasLabel.htmlFor='npc-aliases';aliasLabel.textContent='共用别名（逗号分隔，例如科比、佐巴杨）';const aliasInput=document.createElement('input');aliasInput.id='npc-aliases';aliasInput.placeholder='昵称可用于点名、use/stop及多人互动识别';stage.insertBefore(aliasLabel,$('#npc-background').previousElementSibling);stage.insertBefore(aliasInput,$('#npc-background').previousElementSibling);
const affinityPanel=document.createElement('div');affinityPanel.innerHTML=`<hr><h3>NPC好感度判定</h3><p class="note">按NPC与实际发言者QQ分别记录，范围-100至100。模拟时在同一次AI调用中判断变化，群内只发送模拟正文。关闭后保留已有分数。</p><label><input id="affinity-enabled" type="checkbox">启用自动好感判定</label><label for="affinity-initial">首次互动初始好感（-100–100）</label><input id="affinity-initial" type="number" min="-100" max="100" step="1"><label for="affinity-step">单次最大变化（1–20）</label><input id="affinity-step" type="number" min="1" max="20" step="1"><label for="affinity-prompt">好感判定引导</label><textarea id="affinity-prompt" rows="3" maxlength="4000"></textarea><p class="note">与上方“保存本群模拟与点评设置”一同保存。以下手动调整作用于编辑器中选中的NPC。</p><label for="affinity-uid">玩家QQ</label><input id="affinity-uid" inputmode="numeric"><label for="affinity-score">手动设定好感值（-100–100）</label><input id="affinity-score" type="number" min="-100" max="100" step="1" value="0"><button id="affinity-save">保存该NPC对玩家的好感</button><div id="affinity-records"></div>`;stage.insertBefore(affinityPanel,feedback)
const roster=document.createElement('section');roster.id='npc-roster';roster.style.gridColumn='1 / -1';roster.innerHTML='<h2>全群共用NPC角色库</h2><p class="note">所有群共用NPC名称、背景和别名；下方显示当前群的启停与好感。每8秒同步更新，未保存编辑会保留。可用 人格模拟【NPC名】：【PL行动】直接调用某位NPC。</p><p id="npc-sync" role="status"></p><div id="npc-cards"></div>';panel.insertBefore(roster,stage)
const switches=document.createElement('div');switches.className='presets';switches.innerHTML='<button id="npc-use-all">启用本群全部NPC</button><button id="npc-stop-all">停止本群全部NPC</button>';roster.insertBefore(switches,$('#npc-cards'));const activeNote=document.createElement('p');activeNote.className='note';activeNote.textContent='群内KP/群管理可用.npc use NPC名、.npc stop NPC名、.npc use all、.npc stop all。启用可累加，只有启用中的NPC才能模拟、更新好感及记录本群记忆；停止保留旧记忆。新增背景不会自动启用。以 ** 开头的消息为玩家与KP场外交流：NPC不回应、不记忆，剧本仍记录原文。';roster.insertBefore(activeNote,switches)
const memoryView=document.createElement('details');memoryView.innerHTML='<summary>所选NPC的记忆文档</summary><pre id="npc-memory-view">选中NPC后点击“查看记忆”</pre><button id="npc-memory-refresh">查看记忆</button>';stage.append(memoryView)
const memoryEditor=document.createElement('div');memoryEditor.innerHTML='<label for="npc-memory-editor">修改所选NPC的本群记忆</label><textarea id="npc-memory-editor" rows="10" maxlength="1000000" placeholder="先点击查看记忆读取全文，然后修改。保存前自动备份。"></textarea><button id="npc-memory-save">备份并保存记忆</button> <button id="npc-memory-clear">清空记忆</button><p id="npc-memory-result" role="status"></p><p class="note">.log off后NPC不读写聊天记忆；维护者仍可在此编辑。恢复.log on后按修改后的文档使用，旧模拟上下文会同时重置。</p>';memoryView.append(memoryEditor)
const logPanel=document.createElement('section');logPanel.id='script-log';logPanel.style.gridColumn='1 / -1';logPanel.innerHTML='<h2>剧本记录</h2><p class="note">使用上方选中的群。群内指令：.log on开始/继续、.log off暂停、.log end结束归档、.log name 剧本名命名。KP、群管理和机器人管理员可控制。未命名时会询问名称，命名后开始记录。</p><p id="script-state" role="status">正在读取…</p><label for="script-name">剧本名称（最多80字）</label><input id="script-name" maxlength="80" placeholder="未开始时可预设下一次剧本名"><div class="presets"><button id="script-rename">设定名称</button><button id="script-on">开始 / 继续记录</button><button id="script-off">暂停记录</button><button id="script-end">结束并归档</button></div><p id="script-result" role="status"></p><p class="note">记录本群所有消息文字、媒体标记及机器人实际发送内容；图片/音频原文件不下载。结束时保存开场与结束人物属性，包括本群玩家角色卡、NPC背景与好感度。其他群、暗骰私聊、KP私聊不混入。</p><pre id="script-folders"></pre><details><summary>最近归档的剧本</summary><pre id="script-archives"></pre></details>';panel.insertBefore(logPanel,roster)
const rosterStyle=document.createElement('style');rosterStyle.textContent='#npc-cards{display:grid;grid-template-columns:repeat(auto-fit,minmax(260px,1fr));gap:16px}.npc-card{border:1px solid #455e79;border-radius:16px;background:#0a1524;padding:18px;overflow-wrap:anywhere}.npc-card h3{margin-top:0}.npc-card p{font-size:14px}.npc-card button{padding:8px;font-size:13px;margin:4px}.npc-card pre{max-height:180px;overflow:auto}#affinity-records{overflow-x:auto}#affinity-records table{border-collapse:collapse;width:100%;font-size:14px}#affinity-records td,#affinity-records th{padding:10px;border-bottom:1px solid #344359;text-align:left}';document.head.append(rosterStyle)
const theatreStyle=document.createElement('style');theatreStyle.textContent='#dice-theatre textarea,#npc-list{font:inherit;width:100%;color:#dceaf9;background:#081420;border:1px solid #455e79;border-radius:12px;padding:12px;margin:10px 0}#dice-theatre input[type=checkbox]{width:auto;margin:12px}#dice-theatre hr{border:0;border-top:1px solid #344359;margin:24px 0}';document.head.append(theatreStyle)
const style=document.createElement('style');style.textContent='#kp-group{font:inherit;width:100%;border-radius:12px;padding:12px;background:#081420;border:1px solid #455e79;color:#fff;margin:10px 0}.dice-danger{background:#f0a8a8;color:#3c1010}#dice-management{scroll-margin-top:20px}';document.head.append(style)
const shortcut=document.createElement('a');shortcut.href='#dice-management';shortcut.textContent='KP设置 / 记录清理 ↓';$('header').append(shortcut);const npcShortcut=document.createElement('a');npcShortcut.href='#npc-roster';npcShortcut.textContent='全部NPC / 好感度 ↓';$('header').append(npcShortcut);const logShortcut=document.createElement('a');logShortcut.href='#script-log';logShortcut.textContent='剧本记录 ↓';$('header').append(logShortcut)
let state,busy=false,dirty=false
stage.addEventListener('input',()=>{dirty=true})
async function api(url,body){const r=await fetch(url,body===undefined?{}:{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(body)});const d=await r.json();if(!r.ok)throw Error(d.error||'请求失败');return d}
function current(){const k=state?.keepers?.[$('#kp-group').value];$('#kp-current').textContent=k?`当前KP：${k.name}（QQ ${k.uid}）`:'当前群尚未指定KP';dirty=false;try{localStorage.setItem('dice-npc-group',$('#kp-group').value)}catch{}renderTheatre()}
function theatre(){return {...state?.theatreDefaults,...state?.theatres?.[$('#kp-group').value]}}
function loadNpc(){const name=$('#npc-list').value,n=theatre().npcs?.[name];$('#npc-name').value=name;$('#npc-background').value=n?.background??'';$('#npc-aliases').value=(n?.aliases??[]).filter(x=>x!==name).join('，');renderAffinity(name,n)}
function renderAffinity(name,n){const root=$('#affinity-records');root.replaceChildren();const title=document.createElement('p');title.textContent=name?'正在查看“'+name+'”的好感记录':'先选择NPC查看好感';root.append(title);const entries=Object.entries(n?.affinity??{});if(!entries.length){const p=document.createElement('p');p.className='note';p.textContent='尚无互动记录；首次模拟从本群初始好感开始。';root.append(p);return}const table=document.createElement('table'),head=document.createElement('tr');for(const label of ['玩家','好感','本次变化','原因','更新时间']){const th=document.createElement('th');th.textContent=label;head.append(th)}table.append(head);for(const [uid,a] of entries){const row=document.createElement('tr');for(const value of [(a.name?a.name+' / ':'')+uid,a.score,(a.lastDelta>0?'+':'')+(a.lastDelta??0),a.reason??'',a.updatedAt?new Date(a.updatedAt).toLocaleString():'']){const td=document.createElement('td');td.textContent=String(value);row.append(td)}row.onclick=()=>{$('#affinity-uid').value=uid;$('#affinity-score').value=a.score};table.append(row)}root.append(table)}
function renderTheatre(){const t=theatre();stage.querySelector('h2').textContent='共享NPC资料 / 本群模拟设置 · 群 '+$('#kp-group').value;$('#affinity-enabled').checked=t.affinityEnabled!==false;$('#affinity-initial').value=t.affinityInitial??0;$('#affinity-step').value=t.affinityStep??5;$('#affinity-prompt').value=t.affinityPrompt??'';$('#theatre-enabled').checked=t.enabled!==false;$('#theatre-commentary').checked=t.commentary!==false;$('#theatre-max').value=t.maxChars??500;$('#theatre-prompt').value=t.prompt??'';$('#theatre-comment-prompt').value=t.commentPrompt??'';$('#npc-list').replaceChildren();const empty=document.createElement('option');empty.value='';empty.textContent='选择NPC，或填写新NPC';$('#npc-list').append(empty);for(const name of Object.keys(t.npcs??{})){const o=document.createElement('option');o.value=name;o.textContent=name+(t.selected===name?'（当前）':'');o.selected=t.selected===name;$('#npc-list').append(o)}loadNpc();$('#npc-active').textContent='本群默认NPC：'+(t.selected||'未选择')+' · 启用中：'+(Object.keys(t.npcs??{}).filter(name=>t.npcs[name].active).join('、')||'无')}
async function refresh(){state=await api('/api/dice/status');let saved='';try{saved=localStorage.getItem('dice-npc-group')||''}catch{}const selected=$('#kp-group').value||saved||Object.keys(state.theatres??{}).find(g=>Object.keys(state.theatres[g].npcs??{}).length);$('#kp-group').replaceChildren();for(const gid of state.allowedGroups??[]){const o=document.createElement('option');o.value=gid;o.textContent='群 '+gid;o.selected=gid===selected;$('#kp-group').append(o)}current();renderRoster();$('#keeper-list').textContent=Object.entries(state.keepers??{}).map(([gid,k])=>`群 ${gid}：${k.name}（QQ ${k.uid}）`).join('\n')||'尚未指定KP';$('#dice-player-count').textContent=`当前${state.players}份会话玩家记录，累计${state.rolls}次骰点指令`}
function renderRoster(){const root=$('#npc-cards');root.replaceChildren();let count=0,enabledCount=0;for(const [gid,t] of [[$('#kp-group').value,theatre()]]){if(!state.allowedGroups?.includes(gid))continue;for(const [name,n] of Object.entries(t.npcs??{})){count++;if(n.active)enabledCount++;const card=document.createElement('article');card.className='npc-card';const title=document.createElement('h3');title.textContent=name+(t.selected===name?' · 默认':'')+' · '+(n.active?'启用中':'已停止');const group=document.createElement('p');group.textContent='全群共用 · 当前群 '+gid;const bg=document.createElement('p');bg.textContent=String(n.background??'').slice(0,160)+(String(n.background??'').length>160?'…':'');const scores=document.createElement('pre');scores.textContent='记忆 '+(n.memory?.entries??0)+'条\n'+(Object.entries(n.affinity??{}).map(([uid,a])=>(a.name||uid)+'：'+a.score+'（'+(a.lastDelta>0?'+':'')+(a.lastDelta??0)+'）').join('\n')||'尚无好感记录 · 初始 '+(t.affinityInitial??state.theatreDefaults?.affinityInitial??0));card.append(title,group,bg,scores);function edit(){if(dirty&&!window.confirm('切换NPC将放弃未保存的编辑，继续？'))return false;$('#kp-group').value=gid;current();$('#npc-list').value=name;loadNpc();return true}for(const [label,fn] of [['编辑 / 好感',()=>{if(edit())stage.scrollIntoView({behavior:'smooth'})}],[n.active?'停止此NPC':'启用此NPC',async()=>{if(edit())await action(card.querySelectorAll('button')[1],()=>saveTheatre({activation:{name,active:!n.active}}))}],['复制调用指令',async()=>{const command='人格模拟【'+name+'】：【PL具体行动】';try{await navigator.clipboard.writeText(command);$('#npc-sync').textContent='已复制 '+command+'，在群'+gid+'使用'}catch{$('#npc-sync').textContent=command+'（在群'+gid+'使用）'}}]]){const b=document.createElement('button');b.textContent=label;b.onclick=fn;card.append(b)}root.append(card)}}if(!count)root.textContent='暂无已保存NPC，可在下方新增或由KP私聊录入。';$('#npc-sync').textContent='已同步 '+count+' 位NPC · 同时启用 '+enabledCount+' 位（无数量上限） · '+new Date().toLocaleTimeString()+(dirty?' · 有未保存编辑':'')}
async function action(button,fn){if(busy)return;busy=true;button.disabled=true;try{await fn()}catch(e){$('#dice-management-result').textContent=e.message;$('#theatre-result').textContent=e.message}finally{busy=false;button.disabled=false}}
$('#kp-group').onchange=()=>{current();renderRoster()}
$('#kp-save').onclick=()=>action($('#kp-save'),async()=>{const group=$('#kp-group').value,uid=$('#kp-uid').value.trim();if(!group)throw Error('请先在完整设置中配置群号');if(!/^[1-9]\d{2,19}$/.test(uid))throw Error('请输入有效KP的QQ号');await api('/api/dice/kp',{group,uid,name:$('#kp-name').value.trim()});await refresh();$('#dice-management-result').textContent='本群KP已保存，群里可用.kp 查看。'})
$('#kp-remove').onclick=()=>action($('#kp-remove'),async()=>{const group=$('#kp-group').value;if(!group)throw Error('请选择群');await api('/api/dice/kp',{group,clear:true});await refresh();$('#dice-management-result').textContent='本群KP记录已清除。'})
$('#dice-clear-players').onclick=async()=>{if(busy)return;if(!window.confirm('将清空所有群和私聊中的骰子角色卡、SAN、默认骰面及骰点计数。系统会先备份，保留KP和群开关，不删除QQ聊天记录。确认清空？'))return;await action($('#dice-clear-players'),async()=>{const d=await api('/api/dice/clear-players',{confirm:'CLEAR_DICE_PLAYERS'});await refresh();$('#dice-management-result').textContent=d.unchanged?'当前没有玩家记录，无需重复清理。':`已清理${d.removedPlayers}份玩家记录、${d.removedCards}张角色卡，骰点计数归零。`+(d.backup?'备份：'+d.backup:'')})}
$('#dice-manage-refresh').onclick=()=>action($('#dice-manage-refresh'),refresh)
async function saveTheatre(body){const group=$('#kp-group').value;if(!group)throw Error('请先选择群');await api('/api/dice/theatre',{group,...body});await refresh();if(body.npc&&!body.npc.remove){$('#npc-list').value=body.npc.name;loadNpc()}$('#dice-management-result').textContent=$('#theatre-result').textContent='已保存：NPC资料全群共用，启停和模拟设置作用于所选群。'}
$('#npc-list').onchange=loadNpc
$('#npc-new').onclick=()=>{dirty=true;$('#npc-list').value='';loadNpc();$('#npc-name').focus()}
$('#theatre-save').onclick=()=>action($('#theatre-save'),()=>saveTheatre({enabled:$('#theatre-enabled').checked,commentary:$('#theatre-commentary').checked,maxChars:Number($('#theatre-max').value),prompt:$('#theatre-prompt').value,commentPrompt:$('#theatre-comment-prompt').value,affinityEnabled:$('#affinity-enabled').checked,affinityInitial:Number($('#affinity-initial').value),affinityStep:Number($('#affinity-step').value),affinityPrompt:$('#affinity-prompt').value}))
$('#npc-save').onclick=()=>action($('#npc-save'),()=>saveTheatre({npc:{name:$('#npc-name').value.trim(),background:$('#npc-background').value,aliases:$('#npc-aliases').value.split(/[，,、\n]/).map(s=>s.trim()).filter(Boolean)}}))
$('#npc-select').onclick=()=>action($('#npc-select'),async()=>{const selected=$('#npc-name').value.trim();if(!selected)throw Error('请先选择已保存NPC');await saveTheatre({activation:{name:selected,active:true}})})
$('#npc-delete').onclick=()=>{const name=$('#npc-name').value.trim();if(!name||!window.confirm('删除全群共用NPC“'+name+'”？所有群的此NPC状态及模拟上下文都将移除，记忆原文件保留。'))return;action($('#npc-delete'),()=>saveTheatre({npc:{name,remove:true}}))}
$('#npc-history-clear').onclick=()=>{if(!window.confirm('清除本群全部NPC的最近模拟上下文？背景故事会保留。'))return;action($('#npc-history-clear'),()=>saveTheatre({clearHistory:true}))}
async function refreshScripts(){const d=await api('/api/dice/scripts'),group=$('#kp-group').value,s=d.active?.[group];$('#script-state').textContent='群 '+group+' · '+(s?'“'+(s.name||'待命名')+'” · '+({recording:'记录中',paused:'已暂停','awaiting-name':'等待命名',ending:'归档中'}[s.status]||s.status)+' · '+s.entries+'条消息':'没有未结束的剧本');$('#script-folders').textContent='未结束：'+d.begin+'\n已结束：'+d.end;$('#script-archives').textContent=(d.ended??[]).filter(x=>x.group===group).map(x=>x.name+' · '+x.entries+'条 · '+x.endedAt+'\n'+x.path).join('\n\n')||'本群暂无归档'}
for(const [id,op] of [['script-rename','name'],['script-on','on'],['script-off','off'],['script-end','end']])$('#'+id).onclick=()=>action($('#'+id),async()=>{if(op==='end'&&!window.confirm('结束本群剧本并将聊天及人物属性归档到endscript？'))return;const r=await api('/api/dice/scripts',{group:$('#kp-group').value,op,name:['name','on'].includes(op)?$('#script-name').value.trim():''});$('#script-result').textContent=r.text;await refreshScripts()})
$('#kp-group').addEventListener('change',()=>refreshScripts().catch(e=>$('#script-result').textContent=e.message))
refresh().then(refreshScripts).catch(e=>$('#script-result').textContent=e.message)
setInterval(()=>{if(!busy&&!document.hidden)refreshScripts().catch(e=>$('#script-result').textContent=e.message)},8000)
$('#affinity-save').onclick=()=>action($('#affinity-save'),()=>saveTheatre({affinity:{npc:$('#npc-name').value.trim(),uid:$('#affinity-uid').value.trim(),score:Number($('#affinity-score').value)}}))
$('#npc-use-all').onclick=()=>action($('#npc-use-all'),()=>saveTheatre({activation:{name:'all',active:true}}))
$('#npc-stop-all').onclick=()=>action($('#npc-stop-all'),()=>saveTheatre({activation:{name:'all',active:false}}))
let loadedMemory=null
$('#npc-memory-refresh').onclick=()=>action($('#npc-memory-refresh'),async()=>{const group=$('#kp-group').value,name=$('#npc-name').value.trim();if(!name)throw Error('请先选择NPC');const d=await api('/api/dice/npc-memory?'+new URLSearchParams({group,name}));loadedMemory={group,name};$('#npc-memory-editor').value=d.text??'';$('#npc-memory-view').textContent=name+' · '+(d.active?'启用中':'已停止')+' · '+d.entries+'条记忆 · '+(d.memoryAllowed?'记忆可读写':'log已暂停：NPC不读写记忆')+'\n'+(d.path||'启用并收到消息后建立文档')+'\n\n'+d.recent.map(x=>x.name+'：'+x.text).join('\n')})
async function saveMemory(clear=false){const group=$('#kp-group').value,name=$('#npc-name').value.trim();if(!loadedMemory||loadedMemory.group!==group||loadedMemory.name!==name)throw Error('请先点击查看记忆，核对当前NPC与群');if(!window.confirm(clear?'清空该NPC本群记忆及短期模拟上下文？会先备份。':'用编辑内容替换该NPC本群记忆？会先备份。'))return;const d=await api('/api/dice/npc-memory',{group,name,text:clear?'':$('#npc-memory-editor').value});if(clear)$('#npc-memory-editor').value='';$('#npc-memory-result').textContent='已保存，备份目录：'+d.backup;await refresh()}
$('#npc-memory-save').onclick=()=>action($('#npc-memory-save'),()=>saveMemory())
$('#npc-memory-clear').onclick=()=>action($('#npc-memory-clear'),()=>saveMemory(true))
setInterval(async()=>{if(busy||document.hidden)return;try{const fresh=await api('/api/dice/status');state=fresh;renderRoster();const selected=$('#npc-list').value;if(!dirty){renderTheatre();if(selected&&Object.hasOwn(theatre().npcs??{},selected)){$('#npc-list').value=selected;loadNpc()}}else renderAffinity(selected,theatre().npcs?.[selected])}catch(e){$('#npc-sync').textContent='同步失败：'+e.message}},8000)
